package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Reviewed solutions with narrowly authorized customer state decisions and retained proposal history. */
final class CustomerResolutions {
 private CustomerResolutions() {}
 static Map<String,Object> record(Store.Db db,String id)throws SQLException{var item=CustomerReplies.record(db,id);if(!FieldAccess.allowed(db,Service.schema(db,"customer_case"),"state"))throw new Failure(403,"Case state access required");return item;}
 static Map<String,Object> current(Store.Db db,String id)throws SQLException{var row=db.one("SELECT * FROM os_customer_resolution WHERE record_id=? ORDER BY ordinal DESC LIMIT 1",id);return row==null?map("revision",0,"status","","code","","solution","","reason","","snapshot","","reopened",0):row;}
 static String snapshot(Store.Db db,Map<String,Object> item)throws SQLException{var data=new TreeMap<>(object(item.get("data")));data.remove("state");return DigestUtils.sha256Hex(JSON.writeValueAsString(map("data",data,"schema_version",Approvals.version(Service.schema(db,"customer_case")))));}
 static Map<String,Object> page(Store.Db db,String id)throws SQLException{var item=record(db,id);var current=current(db,id);boolean fresh=current.get("snapshot").equals(snapshot(db,item));var shown=new LinkedHashMap<>(current);shown.remove("snapshot");return map("record",FieldAccess.serialize(db,item),"resolution",shown,"current",fresh,"history",db.all("SELECT ordinal,revision,status,code,solution,proposer_name,reason,created,decided,reopened FROM os_customer_resolution WHERE record_id=? ORDER BY ordinal",id),"can_propose",Set.of("admin","agent").contains(db.viewerRole) && RecordPolicy.allows(Service.schema(db,"customer_case"),"update",db.viewerRole) && CustomerReplies.writable(db),"can_decide","requester".equals(db.viewerRole) && fresh && "pending".equals(current.get("status")),"can_reopen","admin".equals(db.viewerRole));}
 static Map<String,Object> command(Store.Db db,String id,Object input)throws SQLException{
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var item=record(db,id);var current=current(db,id);var body=object(input);String operation=WorkJobs.text(body.get("operation"),8);boolean propose=operation.equals("propose"),decision=Set.of("accept","reject").contains(operation);require(Set.of("propose","accept","reject","withdraw","reopen").contains(operation),"Choose a resolution operation");var keys=new HashSet<>(Set.of("operation","revision","record_revision"));keys.addAll(propose?Set.of("code","solution"):Set.of("reason"));require(body.keySet().equals(keys),"Provide only the selected resolution fields");ProblemInvestigations.revision(body.get("revision"),current.get("revision"));ProblemInvestigations.revision(body.get("record_revision"),item.get("revision"));String actor=Service.account(db,db.viewerId).get("name").toString(),state=object(item.get("data")).get("state").toString(),target="working",reason=propose?"":WorkJobs.text(body.get("reason"),4000);
  if(decision){if(!"requester".equals(db.viewerRole))throw new Failure(403,"Only the current customer can decide a proposed solution");}
  else{if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Support staff access required");RecordPolicy.require(Service.schema(db,"customer_case"),"update",db.viewerRole);if(!CustomerReplies.writable(db))throw new Failure(403,"Case description write access required");}
  if(propose){require(state.equals("working"),"Propose a solution while the case is in progress");long count=db.count("SELECT COUNT(*) FROM os_customer_resolution WHERE record_id=?",id);require(count<50,"At most 50 solution proposals belong to one case");String code=WorkJobs.text(body.get("code"),12),solution=WorkJobs.text(body.get("solution"),4000);require(Set.of("solved","workaround","duplicate","unavailable").contains(code),"Choose a resolution code");db.update("INSERT INTO os_customer_resolution(resolution_id,record_id,ordinal,revision,status,code,solution,proposer_name,reason,created,decided,snapshot) VALUES(?,?,?,1,'pending',?,?,?,'',?,'',?)",Values.id(),id,count+1,code,solution,actor,now(),snapshot(db,item));target="resolved";}
  else if(operation.equals("reopen")){if(!"admin".equals(db.viewerRole))throw new Failure(403,"Administrator reopening required");require(state.equals("closed") && current.get("status").equals("accepted"),"Reopen only an accepted closed resolution");db.update("UPDATE os_customer_resolution SET reopened=1,revision=revision+1 WHERE resolution_id=?",current.get("resolution_id"));}
  else{require(state.equals("resolved") && current.get("status").equals("pending"),"A pending resolved solution is required");if(decision && !current.get("snapshot").equals(snapshot(db,item)))throw new Failure(409,"The case or its policy changed; ask support to renew the solution");String status=operation.equals("accept")?"accepted":operation.equals("reject")?"rejected":"withdrawn";db.update("UPDATE os_customer_resolution SET status=?,reason=?,decided=?,revision=revision+1 WHERE resolution_id=?",status,reason,now(),current.get("resolution_id"));if(operation.equals("accept"))target="closed";}
  if(decision)decide(db,item,target,actor);else try{db.customerResolutionReopen=operation.equals("reopen");Service.update(db,"customer_case",item,map("state",target),actor,db.viewerRole,body.get("record_revision").toString());}finally{db.customerResolutionReopen=false;}Service.audit(db,item,actor,"customer.resolution_"+operation,map("reason",reason));return page(db,id);
 }
 private static void decide(Store.Db db,Map<String,Object> item,String target,String actor)throws SQLException{
  var schema=Service.schema(db,"customer_case");var data=object(item.get("data"));if(!((List<?>)object(schema.get("flow")).getOrDefault(data.get("state"),List.of())).contains(target))throw new Failure(409,"Current case flow does not permit this decision");FieldAccess.writing(db,schema,map("state",target));TypedFields.writing(schema,data,map("state",target),db.viewerRole);TypedFields.transition(schema,target,db.viewerRole);var proposed=new LinkedHashMap<>(data);proposed.put("state",target);TypedFields.check(db,schema,proposed);var before=Service.serialize(item);data.put("state",target);item.putAll(map("updated",now(),"updater",actor,"revision",((Number)item.get("revision")).intValue()+1));Service.save(db,item);Service.audit(db,item,actor,"updated",map("before",before,"after",Service.serialize(item)));
 }
 static boolean reopening(Store.Db db,Map<String,Object> item,Object target){return db.customerResolutionReopen && "customer_case".equals(item.get("table")) && "working".equals(target);}
 static void guard(Store.Db db,Map<String,Object> item)throws SQLException{
  if(!"customer_case".equals(item.get("table")))return;var current=current(db,item.get("sys_id").toString());if(((Number)current.get("revision")).intValue()==0)return;String state=object(item.get("data")).get("state").toString(),status=current.get("status").toString();var previous=db.one("SELECT data FROM os_record WHERE sys_id=?",item.get("sys_id"));String before=object(previous.get("data")).get("state").toString();
  if(Set.of("resolved","closed").contains(state) && !(status.equals(state.equals("resolved")?"pending":"accepted") && ((Number)current.get("reopened")).intValue()==0 && current.get("snapshot").equals(snapshot(db,item))))throw new Failure(409,"A current reviewed customer solution is required for this state");
  if(before.equals("resolved") && !state.equals("resolved") && !(state.equals("closed") || state.equals("working") && Set.of("rejected","withdrawn").contains(status)))throw new Failure(409,"The customer must decide, or support must withdraw, this solution");
  if(before.equals("closed") && !state.equals("closed") && !reopening(db,item,state))throw new Failure(409,"Use the administrator resolution reopening action");
 }
}
